    close_count = lst[0].count(')')

    if open_count != close_count:
        return 'No'

    open_count = lst[1].count('(')
    close_count = lst[1].count(')')

    if open_count != close_count:
        return 'No'

    combinations = [lst[0] + lst[1], lst[1] + lst[0]]

    for combination in combinations:
        if is_balanced(combination):
